const formatDate = (value) => value ? new Intl.DateTimeFormat('fr-FR', { dateStyle: 'medium' }).format(new Date(`${value}T00:00:00`)) : 'Non renseignée';
const formatBytes = (value) => value >= 1048576 ? `${(value / 1048576).toFixed(1)} Mo` : `${Math.max(1, Math.round(value / 1024))} Ko`;
const archiveEmployee = () => archiveForm.delete(`/administration/employees/${props.employee.uuid}`);
const restoreEmployee = () => router.post(`/administration/employees/${props.employee.uuid}/restore`);
const uploadDocument = () => uploadForm.post('/administration/documents', { forceFormData: true, onSuccess: () => uploadForm.reset('title', 'issued_on', 'notes', 'attestation_type_uuid', 'employment_contract_uuid', 'leave_request_uuid', 'file') });
const openDocumentArchive = (document) => { documentArchiveTarget.value = document; documentArchiveForm.reset(); };
const archiveDocument = () => documentArchiveForm.delete(`/administration/documents/${documentArchiveTarget.value.uuid}`, { onSuccess: () => { documentArchiveTarget.value = null; documentArchiveForm.reset(); } });
const restoreDocument = (document) => router.post(`/administration/documents/${document.uuid}/restore`);
</script>

