hive" /></Button><Button v-if="document.archived && can('hr_documents.restore')" icon size="rg" variant="white-outline" title="Restaurer" @click="restoreDocument(document)"><Icon name="undo" /></Button></div></div><form v-if="documentArchiveTarget?.uuid === document.uuid" class="mt-3 flex flex-col gap-2 border-t border-gray-200 pt-3 dark:border-gray-800 sm:flex-row" @submit.prevent="archiveDocument"><Input v-model="documentArchiveForm.reason" class="flex-1" placeholder="Motif d’archivage" required /><Button size="sm" variant="danger" :disabled="documentArchiveForm.processing">Archiver</Button><Button size="sm" type="button" variant="white-outline" @click="documentArchiveTarget = null">Annuler</Button></form></article><div v-if="documents.length === 0" class="rounded-lg border border-dashed border-gray-200 px-4 py-8 text-center text-sm text-slate-400 dark:border-gray-800">Aucun document dans ce dossier.</div></div>

