rror></div><div><label class="mb-1 block text-xs font-bold text-slate-500">Date du document</label><input v-model="uploadForm.issued_on" type="date" class="h-10 w-full rounded-lg border border-gray-200 bg-white px-3 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white"></div><div><label class="mb-1 block text-xs font-bold text-slate-500">Fichier</label><input type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx,.xls,.xlsx" class="block w-full text-xs text-slate-500" required @change="uploadForm.file = $event.target.files[0] ?? null"><FormError v-if="uploadForm.errors.file">{{ uploadForm.errors.file }}</FormError></div><div><label class="mb-1 block text-xs font-bold text-slate-500">Notes</label><textarea v-model="uploadForm.notes" class="min-h-20 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white" /></div><Button block size="rg" :disabled="uploadForm.processing || !uploadForm.file"><Icon name="upload-cloud" /><span class="ms-2">{{ uploadForm.processing ? 'Envoi…' : 'Ajouter au dossier' }}</span></Button></div></form></div></section>
